/**
 * SADAF | API Route — AI design image generation (AI Studio)
 *
 * POST /api/gemini/generate-pattern
 *
 * Body: { prompt: string; clothingType: string; styleModifier?: string;
 *         primaryColor?: string; accentColor?: string }
 * Response: { generatedImageUrl: string } — a base64 image data URL.
 *
 * FREE BY DEFAULT: images are generated by **Pollinations.ai** — a free,
 * keyless text-to-image API. The prompt travels in the URL path (their POST
 * endpoint ignores the JSON body), and the seed is derived from the prompt so
 * repeat generations of the same design hit their cache and return instantly.
 * Because it is a free service, the backend is occasionally flaky, so the
 * request is retried with backoff before giving up.
 *
 * QUALITY: images are requested at 1024x1024 (Pollinations delivers ~768px)
 * with the `dreamshaper` model — a side-by-side comparison showed noticeably
 * richer, more symmetric patterns than the flat 512px default render.
 *
 * Fallback: if Pollinations is unreachable, the route tries Gemini
 * (`gemini-2.5-flash-image`) when `GEMINI_API_KEY` is set. Google's image
 * models require a billing account as of 2026 (free image quota is 0), so
 * Gemini is an optional quality upgrade, not the default.
 *
 * If every provider fails → 502, and the AI Studio client shows the seeded
 * procedural SVG pattern instead (studio stays fully usable).
 *
 * GET /api/gemini/generate-pattern?check=1 — lightweight health check.
 */

import { NextResponse } from 'next/server';

const POLLINATIONS_ENDPOINT = 'https://image.pollinations.ai/prompt';
const GENERATIVE_ENDPOINT = 'https://generativelanguage.googleapis.com/v1beta/models';

/** Gemini image model — used only when a key is configured. */
const GEMINI_IMAGE_MODEL = 'gemini-2.5-flash-image';

/** Quality settings for Pollinations. 512px looked flat and lost the fine
 * geometric detail in the prompt; 1024px renders noticeably richer, symmetric
 * patterns. `dreamshaper` scored highest on detail/sharpness in a side-by-side
 * model comparison (flux, turbo, sdxl, dreamshaper, default). */
const POLLINATIONS_WIDTH = 1024;
const POLLINATIONS_HEIGHT = 1024;
const POLLINATIONS_MODEL = 'dreamshaper';

/** Pollinations is free and occasionally flaky — retry before giving up. */
const POLLINATIONS_MAX_ATTEMPTS = 3;

interface GeneratePatternRequestBody {
    prompt: string;
    clothingType: string;
    styleModifier?: string;
    primaryColor?: string;
    accentColor?: string;
}

interface GenerateResult {
    ok: boolean;
    status: number;
    mimeType?: string;
    base64?: string;
    detail?: string;
}

/** GET /api/gemini/generate-pattern?check=1 — is image generation available? */
export async function GET(request: Request) {
    const { searchParams } = new URL(request.url);
    if (searchParams.get('check') === '1') {
        return NextResponse.json({
            ok: true,
            provider: 'pollinations',
            model: POLLINATIONS_MODEL,
            size: `${POLLINATIONS_WIDTH}x${POLLINATIONS_HEIGHT}`,
            geminiConfigured: !!process.env.GEMINI_API_KEY,
        });
    }
    return NextResponse.json({ ok: false }, { status: 404 });
}

/** Map the studio's swatch hexes to natural color names — image models follow
 * natural language better than hex codes. */
const SWATCH_COLOR_NAMES: Record<string, string> = {
    '#0A0F2C': 'deep navy blue',
    '#2B3B73': 'royal blue',
    '#EAE0D6': 'ivory cream',
    '#232A3B': 'dark slate',
    '#141720': 'charcoal black',
    '#C9A84C': 'gold',
};

function hexToColorName(hex: string | undefined, fallback: string): string {
    if (!hex) return fallback;
    return SWATCH_COLOR_NAMES[hex.toUpperCase()] ?? hex;
}

/** Compose a rich, on-brand textile-pattern prompt from the studio inputs.
 * The image is projected as a pattern overlay on the garment mockup, so it
 * must be a flat, tileable 2D design — people/scenery are explicitly banned. */
function buildImagePrompt(body: GeneratePatternRequestBody): string {
    const style = body.styleModifier ? `${body.styleModifier} style, ` : '';
    const primaryName = hexToColorName(body.primaryColor, 'deep navy blue');
    const accentName = hexToColorName(body.accentColor, 'gold');
    return [
        'Tileable seamless fabric pattern,',
        style,
        `${body.prompt}.`,
        `${primaryName} fabric background with ${accentName} accents.`,
        'Flat 2D textile design, evenly repeating motifs, high-detail weave texture.',
        'NO people, NO faces, NO figures, NO characters, NO buildings, NO scenery — abstract geometric pattern only.',
    ]
        .filter(Boolean)
        .join(' ');
}

/** FNV-1a — stable seed so identical prompts reuse Pollinations' image cache. */
function promptSeed(input: string): number {
    let hash = 2166136261;
    for (let i = 0; i < input.length; i++) {
        hash ^= input.charCodeAt(i);
        hash = Math.imul(hash, 16777619);
    }
    return hash >>> 0;
}

function delay(milliseconds: number): Promise<void> {
    return new Promise((resolve) => setTimeout(resolve, milliseconds));
}

/** Pollinations.ai — free, keyless text-to-image, prompt in the URL path. */
async function generateWithPollinations(imagePrompt: string, seed: number): Promise<GenerateResult> {
    const url = new URL(`${POLLINATIONS_ENDPOINT}/${encodeURIComponent(imagePrompt)}`);
    url.searchParams.set('width', String(POLLINATIONS_WIDTH));
    url.searchParams.set('height', String(POLLINATIONS_HEIGHT));
    url.searchParams.set('model', POLLINATIONS_MODEL);
    url.searchParams.set('nologo', 'true');
    url.searchParams.set('seed', String(seed));

    for (let attempt = 1; attempt <= POLLINATIONS_MAX_ATTEMPTS; attempt++) {
        try {
            const response = await fetch(url.toString(), {
                signal: AbortSignal.timeout(60_000),
            });

            if (!response.ok) {
                const body = await response.text().catch(() => '');
                if (attempt < POLLINATIONS_MAX_ATTEMPTS) {
                    console.error(
                        `[pollinations] attempt ${attempt}/${POLLINATIONS_MAX_ATTEMPTS} HTTP ${response.status} — retrying`
                    );
                    await delay(1500 * attempt);
                    continue;
                }
                return { ok: false, status: response.status, detail: body };
            }

            const buffer = await response.arrayBuffer();
            if (buffer.byteLength === 0) {
                return { ok: false, status: 502, detail: 'Pollinations returned an empty image' };
            }
            return {
                ok: true,
                status: 200,
                mimeType: response.headers.get('content-type')?.split(';')[0] || 'image/jpeg',
                base64: Buffer.from(buffer).toString('base64'),
            };
        } catch (error) {
            const isTimeout = error instanceof Error && error.name === 'TimeoutError';
            if (attempt < POLLINATIONS_MAX_ATTEMPTS) {
                console.error(
                    `[pollinations] attempt ${attempt}/${POLLINATIONS_MAX_ATTEMPTS} ${isTimeout ? 'timed out' : 'network error'} — retrying`
                );
                await delay(1500 * attempt);
                continue;
            }
            if (isTimeout) {
                return { ok: false, status: 504, detail: 'Pollinations timed out' };
            }
            return { ok: false, status: 502, detail: 'Pollinations network error' };
        }
    }

    return { ok: false, status: 502, detail: 'Pollinations unreachable after retries' };
}

/** Gemini image model (generateContent) — requires a configured key + billing. */
async function generateWithGemini(imagePrompt: string, apiKey: string): Promise<GenerateResult> {
    const response = await fetch(
        `${GENERATIVE_ENDPOINT}/${GEMINI_IMAGE_MODEL}:generateContent?key=${apiKey}`,
        {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                contents: [{ parts: [{ text: imagePrompt }] }],
                generationConfig: { responseModalities: ['IMAGE', 'TEXT'] },
            }),
            signal: AbortSignal.timeout(60_000),
        }
    );
    if (!response.ok) {
        return {
            ok: false,
            status: response.status,
            detail: await response.text().catch(() => ''),
        };
    }
    const data = await response.json();
    const parts: Array<{ inlineData?: { mimeType?: string; data?: string } }> =
        data?.candidates?.[0]?.content?.parts;
    const imagePart = Array.isArray(parts)
        ? parts.find((part) => part?.inlineData)
        : undefined;
    const inlineData = imagePart?.inlineData;
    if (!inlineData?.data) {
        return { ok: false, status: 502, detail: 'Gemini returned no image data' };
    }
    return {
        ok: true,
        status: 200,
        mimeType: inlineData.mimeType || 'image/png',
        base64: inlineData.data,
    };
}

export async function POST(request: Request) {
    let body: GeneratePatternRequestBody;
    try {
        body = await request.json();
    } catch {
        return NextResponse.json({ error: 'Invalid JSON body' }, { status: 400 });
    }

    if (!body.prompt?.trim() || !body.clothingType?.trim()) {
        return NextResponse.json(
            { error: 'Missing required fields: prompt, clothingType' },
            { status: 400 }
        );
    }

    const imagePrompt = buildImagePrompt(body);
    // Pollinations' backend rejects large 32-bit seeds ("Query parameter
    // validation failed") — clamp to a small range. Still deterministic, so
    // identical prompts reuse their image cache.
    const seed = promptSeed(imagePrompt) % 100_000;

    // 1) Pollinations — free, no key. This is the default path.
    const pollinationsResult = await generateWithPollinations(imagePrompt, seed);
    if (pollinationsResult.ok) {
        return NextResponse.json({
            generatedImageUrl: `data:${pollinationsResult.mimeType};base64,${pollinationsResult.base64}`,
        });
    }

    // 2) Gemini — only when a key is configured (image models need billing in 2026).
    const apiKey = process.env.GEMINI_API_KEY;
    if (apiKey) {
        try {
            const geminiResult = await generateWithGemini(imagePrompt, apiKey);
            if (geminiResult.ok) {
                return NextResponse.json({
                    generatedImageUrl: `data:${geminiResult.mimeType};base64,${geminiResult.base64}`,
                });
            }
            return NextResponse.json(
                {
                    error: `Gemini image API error (${geminiResult.status}) — Pollinations was also unreachable`,
                    detail: geminiResult.detail,
                },
                { status: 502 }
            );
        } catch (error) {
            if (error instanceof Error && error.name === 'TimeoutError') {
                return NextResponse.json({ error: 'Image generation timed out' }, { status: 504 });
            }
        }
    }

    return NextResponse.json(
        {
            error: 'Image generation failed on all providers',
            detail: pollinationsResult.detail,
        },
        { status: 502 }
    );
}
